const number=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(n);
const date=v=>v?new Date(v).toLocaleString('en-GB',{timeZone:'Asia/Baghdad',hour12:true}):'غير متاح';
export function usageState(value,limit){if(value==null||!Number.isFinite(Number(value))||!limit)return {percent:null,label:'غير متاح',tone:'unknown'};const percent=Number(value)/limit*100;return {percent,label:percent>=100?'وصل الحد':percent>=90?'قريب من الامتلاء':percent>=75?'تنبيه':'ضمن الحد',tone:percent>=90?'danger':percent>=75?'warning':'good'};}
export function remainingPeriod(end,now=Date.now()){if(!end)return 'موعد التجديد غير متاح من الربط الحالي';const ms=new Date(end).getTime()-now;if(!Number.isFinite(ms))return 'موعد غير صالح';if(ms<=0)return 'انتهت الفترة المسجلة؛ حدّث القراءة من المزود';return `${number(Math.floor(ms/86400000))} يوم و${number(Math.floor(ms/3600000)%24)} ساعة و${number(Math.floor(ms/60000)%60)} دقيقة`}
export function createServerMonitor({document,rpc,run}){
 const root=document.getElementById('serverMonitor');let result,pending=null;
 const el=(tag,value,cls)=>{const e=document.createElement(tag);if(value!=null)e.textContent=value;if(cls)e.className=cls;return e;};
 const link=(title,url)=>{const a=el('a',title,'secondary monitor-link');a.href=url;a.target='_blank';a.rel='noopener noreferrer';return a;};
 function stat(parent,label,value,note){const c=el('article',null,'monitor-stat');c.append(el('h3',label),el('strong',value==null?'غير متاح':number(value)),el('p',note));parent.append(c);}
 function meter(parent,label,value,limit,unit,note){const state=usageState(value,limit),c=el('article',null,'monitor-resource '+state.tone);c.append(el('h3',label),el('strong',value==null?'غير متاح':`${number(value)} ${unit}`),el('span',state.label,'monitor-badge'));if(limit){c.append(el('p',`الحد المشمول: ${number(limit)} ${unit}`));if(state.percent!=null){const progress=el('progress');progress.max=100;progress.value=Math.min(100,state.percent);progress.setAttribute('aria-label',label);c.append(progress,el('p',`${number(state.percent)}% · المتبقي ${number(Math.max(0,limit-value))} ${unit}`));}}c.append(el('small',note));parent.append(c);}
 function render(){
  const {provider:p={},live:l={},at}=result;root.replaceChildren();
  const head=el('div',null,'card monitor-heading'),refresh=el('button','تحديث الآن');refresh.type='button';refresh.onclick=()=>run(load);head.append(el('h2','مراقبة السيرفر'),el('p','قراءات السيرفر المباشرة منفصلة عن حصص المزود والخرائط.'),refresh,el('small',`آخر قراءة مباشرة: ${date(at)} · توقيت بغداد`));root.append(head);
  const billing=el('div',null,'card');billing.append(el('h2','الخطة والتجديد والمبلغ'));
  const names={free:'مجانية',pro:'Pro',team:'Team',custom:'مخصصة'};billing.append(el('p',`الخطة حسب آخر تحقق: ${names[p.plan]||'غير متاحة'} · تاريخ التحقق ${date(p.verified_at)}`));
  const countdown=el('p',remainingPeriod(p.period_end));billing.append(el('p',`الفترة المسجلة: ${date(p.period_start)} ← ${date(p.period_end)}`),countdown);
  billing.append(el('p',p.amount_usd==null?'المبلغ المطلوب: غير متاح؛ راجع الفاتورة الرسمية.':`المبلغ المسجل من الفاتورة: $${number(p.amount_usd)} · قراءة محفوظة بتاريخ ${date(p.verified_at)}`));
  billing.append(el('p','عند التجديد تبدأ حصص الاستخدام الدوري من جديد. حجم قاعدة البيانات والملفات لا ينحذف ولا يصفر. الاشتراك المدفوع لا يرجع للمجاني تلقائيًا.'));
  billing.append(link('الاستهلاك الرسمي','https://supabase.com/dashboard/org/kgjbrfjchkxfjnkjdpxy/usage'),link('الفاتورة والتجديد','https://supabase.com/dashboard/org/kgjbrfjchkxfjnkjdpxy/billing'));root.append(billing);
  const resources=el('div',null,'card');resources.append(el('h2','المساحة والاتصالات · قراءة مباشرة'));const grid=el('div',null,'monitor-grid');resources.append(grid);root.append(resources);
  const free=p.plan==='free',known=free||p.plan==='pro'||p.plan==='team';
  meter(grid,'حجم قاعدة البيانات',l.database_bytes/1048576,free?500:null,'MB','حجم قاعدة البيانات عبر PostgreSQL؛ لا يقيس امتلاء القرص أو WAL. حد الخطة المجانية حسب آخر تحقق للخطة.');
  meter(grid,'الملفات المخزونة',l.storage_bytes/1e9,known?(free?1:100):null,'GB','الحجم الحالي حسب بيانات الملفات؛ فاتورة التخزين تعتمد متوسط الاستخدام خلال الفترة.');
  meter(grid,'اتصالات PostgreSQL',l.database_connections,l.database_connection_limit,'اتصال','اتصالات قاعدة البيانات الحالية؛ تختلف عن اتصالات Realtime ومستخدمي الخريطة.');
  const monthly=el('div',null,'card');monthly.append(el('h2','الحصص الدورية · قراءة المزود المحفوظة'));const mgrid=el('div',null,'monitor-grid');monthly.append(mgrid);root.append(monthly);
  const expired=!p.period_end||!p.period_start||Date.parse(p.period_end)<=Date.now()||Date.parse(p.period_start)>Date.now();
  const value=k=>expired?null:p[k];
  for(const [key,label,limit,unit] of [['egress','نقل البيانات',free?5:250,'GB'],['cached_egress','نقل البيانات المخزنة مؤقتًا',free?5:250,'GB'],['edge','استدعاءات دوال السيرفر',free?500000:2000000,'استدعاء'],['realtime','رسائل التحديث المباشر',free?2000000:5000000,'رسالة'],['peak','ذروة اتصالات Realtime',free?200:500,'اتصال'],['mau','المستخدمون النشطون شهريًا',free?50000:100000,'مستخدم']])meter(mgrid,label,value(key),known?limit:null,unit,expired?'لا توجد قراءة مزود ضمن فترة سارية؛ لا يعني الاستهلاك صفرًا.':`قراءة محفوظة وليست اتصالًا مباشرًا بالفوترة · ${date(p.verified_at)}`);
  monthly.append(el('p','الحصص تخص المؤسسة وقد تشمل مشاريع أخرى. تنبيهات 75% و90% و100% تظهر للقراءات المعروفة فقط. لا تعني سلامة مورد واحد أن السيرفر كله ضمن الحد.'));
  const ops=el('div',null,'card');ops.append(el('h2','التتبع والتوزيع والإشعارات'));const og=el('div',null,'monitor-grid');ops.append(og);root.append(ops);
  stat(og,'كباتن بموقع حديث',l.tracking_fresh,'متصل وموقعه خلال آخر دقيقتين.');stat(og,'كباتن بموقع قديم',l.tracking_stale,'متصل لكن موقعه قديم أو غير موجود.');stat(og,'رحلات جارية',l.rides_active,'مقبولة أو الكابتن واصل أو قيد الرحلة.');stat(og,'رحلات تبحث عن كابتن',l.rides_searching,'طلبات بحالة قيد البحث.');stat(og,'عروض تنتظر الرد',l.offers_pending,'عروض سارية لم تنته مهلتها.');stat(og,'إشعارات تنتظر الإرسال',l.push_pending,'عدد سجلات قائمة الإرسال الحالية.');stat(og,'إشعارات فشل إرسالها',l.push_failed,'سجلات بحالة failed.');stat(og,'إرسال Push خلال 24 ساعة',l.push_sent_24h,'إرسال من السيرفر؛ لا يثبت وصول الإشعار للجهاز.');stat(og,'إشعارات أنشئت خلال 24 ساعة',l.notifications_24h,'عدد سجلات الإشعارات، وليس استهلاك Firebase.');
  ops.append(el('p',`آخر تشغيل لعامل توزيع الرحلات: ${date(l.dispatch_worker_at)} · ${l.dispatch_has_error?'يوجد خطأ مسجل يحتاج مراجعة':'لا يوجد خطأ مسجل'}`));
  const maps=el('div',null,'card');maps.append(el('h2','الخريطة · OpenStreetMap'),el('p',value('map_users')==null?'عدد مستخدمي الخريطة: غير متاح؛ التطبيق الحالي لا يرسل حدث فتح الخريطة.':`عدد مستخدمي الخريطة المسجل: ${number(value('map_users'))} · قراءة محفوظة ${date(p.verified_at)}`),el('p','عدد الكباتن المتتبَّعين أعلاه لا يساوي عدد مستخدمي الخريطة. بيانات OSM منفصلة عن مزود البلاطات والبحث والمسارات؛ لا توجد هنا فاتورة موثقة لهذه الخدمات.'),el('p','المبلغ المطلوب للخريطة: غير متاح من الربط الحالي.'));root.append(maps);
  const details=el('details',null,'card');details.append(el('summary','تسجيل قراءة رسمية من المزود'));const form=el('form');form.className='monitor-form';
  form.append(el('p','أدخل فقط الأرقام والتواريخ من لوحة المزود. الحقول الفارغة تبقى غير متاحة. هذا يحفظ قراءة للمراقبة ولا يغير اشتراكك.'));
  const fields={};const add=(key,label,type='number')=>{const labelEl=el('label',label,'field'),input=el('input');input.type=type;input.name=key;if(type==='number'){input.min=0;input.max=1e15;input.step='any';}if(type==='date')input.value=p[key]?new Date(p[key]).toLocaleDateString('en-CA',{timeZone:'Asia/Baghdad'}):'';else input.value=p[key]??'';labelEl.append(input);fields[key]=input;form.append(labelEl);};
  const label=el('label','الخطة','field'),select=el('select');for(const [key,name]of Object.entries(names)){const option=el('option',name);option.value=key;select.append(option);}select.value=p.plan||'free';fields.plan=select;label.append(select);form.append(label);
  add('period_start','بداية فترة الاستهلاك · توقيت بغداد','date');add('period_end','موعد التجديد · توقيت بغداد','date');
  for(const [key,name]of [['egress','نقل البيانات GB'],['cached_egress','نقل البيانات المخزنة GB'],['edge','استدعاءات الدوال'],['realtime','رسائل Realtime'],['peak','ذروة اتصالات Realtime'],['mau','المستخدمون النشطون شهريًا'],['map_users','مستخدمو الخريطة حسب المزود'],['amount_usd','المبلغ المطلوب حسب فاتورة Supabase · دولار']])add(key,name);
  const save=el('button','حفظ القراءة الرسمية'),feedback=el('p');feedback.setAttribute('role','status');save.type='submit';form.append(save,feedback);form.onsubmit=e=>{e.preventDefault();run(async()=>{save.disabled=true;try{const data={};for(const [key,input]of Object.entries(fields)){data[key]=input.value===''?null:input.type==='number'?Number(input.value):input.type==='date'?input.value+'T00:00:00+03:00':input.value;}await rpc('save_provider',data);await load();}catch(error){feedback.textContent='تعذر حفظ القراءة؛ تحقق من الفترة والأرقام وحاول ثانية.';throw error;}finally{save.disabled=false;}});};details.append(form);root.append(details);
 }
 async function load(){if(pending)return pending;pending=(async()=>{try{result=await rpc('read');render();}catch(error){root.replaceChildren(el('div','تعذر جلب قراءة السيرفر. اضغط إعادة المحاولة؛ لا توجد قراءة حديثة.','card'));const retry=el('button','إعادة المحاولة');retry.onclick=()=>run(load);root.append(retry);throw error;}finally{pending=null;}})();return pending;}
 return {load};
}
